WITH src AS (SELECT *, CASE WHEN budget >= 4206000 THEN 'High' WHEN budget >= 612000 THEN 'Medium' ELSE 'Low' END budget_band FROM departments WHERE location IN ('London', 'New York', 'Chiang Mai') AND budget < 3809000), budget_bucket_summary AS (SELECT CASE WHEN budget >= 3166000 THEN 'high' WHEN budget >= 1135000 THEN 'mid' ELSE 'low' END budget_bucket, COUNT(DISTINCT budget) unique_locations, ROUND(STDDEV(budget), 2) stddev_budget FROM src GROUP BY CASE WHEN budget >= 3166000 THEN 'high' WHEN budget >= 1135000 THEN 'mid' ELSE 'low' END) SELECT budget_bucket, unique_locations FROM budget_bucket_summary ORDER BY 1 LIMIT 1
